package com.ajay.moneygrow;
import android.app.*;import android.os.Bundle;import android.content.Intent;import android.database.Cursor;import android.graphics.Typeface;import android.view.View;import android.widget.*;import android.text.InputType;import java.text.NumberFormat;import java.util.Locale;
public class MainActivity extends Activity {
 Db db;LinearLayout root,list;TextView balance,income,expense;NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("en","IN"));
 int pad(int x){return(int)(x*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xff17211b);return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);render();}
 void render(){
  ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(pad(20),pad(26),pad(20),pad(20));root.setBackgroundColor(0xfff5f7f4);scroll.addView(root);setContentView(scroll);
  TextView brand=text("MoneyGrow",28);brand.setTypeface(null,Typeface.BOLD);root.addView(brand);TextView sub=text("Your money, on your phone",14);sub.setPadding(0,pad(4),0,pad(18));root.addView(sub);
  LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(pad(18),pad(18),pad(18),pad(18));card.setBackgroundColor(0xffdcefe3);root.addView(card);card.addView(text("NET FLOW",12));balance=text("₹0",30);balance.setTypeface(null,Typeface.BOLD);card.addView(balance);
  LinearLayout row=new LinearLayout(this);row.setPadding(0,pad(14),0,pad(14));root.addView(row);income=text("↑ Income\n₹0",17);expense=text("↓ Expenses\n₹0",17);row.addView(income,new LinearLayout.LayoutParams(0,-2,1));row.addView(expense,new LinearLayout.LayoutParams(0,-2,1));
  Button add=new Button(this);add.setText("+ Add income / expense");add.setOnClickListener(v->addDialog());root.addView(add);
  Button auto=new Button(this);auto.setText("Set up automatic detection");auto.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Allow notification access?").setMessage("Android notification access is powerful. While enabled, Android can deliver notifications from across the device. MoneyGrow filters likely payment alerts and stores a generic label, amount, direction, category, date and app package only. Nothing is uploaded, but detection can miss or misread alerts.").setNegativeButton("Not now",null).setPositiveButton("Open settings",(d,w)->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))).show());root.addView(auto);
  TextView privacy=text("PRIVACY • Stored locally on this phone. No account, cloud sync, analytics or internet permission. Review detected transactions.",12);privacy.setPadding(0,pad(8),0,pad(10));root.addView(privacy);
  Button wipe=new Button(this);wipe.setText("Delete all transaction data");wipe.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Delete all transactions?").setMessage("This permanently deletes MoneyGrow transaction records on this phone.").setNegativeButton("Cancel",null).setPositiveButton("Delete all",(d,w)->{db.deleteAllTransactions();refresh();}).show());root.addView(wipe);
  TextView h=text("Recent transactions",20);h.setTypeface(null,Typeface.BOLD);h.setPadding(0,pad(14),0,pad(8));root.addView(h);list=new LinearLayout(this);list.setOrientation(1);root.addView(list);refresh();
 }
 void refresh(){double inc=db.total(true),out=db.total(false);income.setText("↑ Income\n"+money.format(inc));expense.setText("↓ Expenses\n"+money.format(out));balance.setText(money.format(inc-out));list.removeAllViews();Cursor c=db.all();
  if(!c.moveToFirst())list.addView(text("No transactions yet. Add one manually or enable notification detection.",14));else do{String title=c.getString(1);double amt=c.getDouble(2);boolean in=c.getInt(3)==1;String cat=c.getString(4),date=c.getString(5);LinearLayout item=new LinearLayout(this);item.setOrientation(1);item.setPadding(0,pad(12),0,pad(12));TextView a=text((in?"+ ":"− ")+money.format(amt)+" • "+title,16);a.setTypeface(null,Typeface.BOLD);item.addView(a);item.addView(text(cat+" · "+date,12));list.addView(item);View line=new View(this);line.setBackgroundColor(0xffdfe5df);list.addView(line,new LinearLayout.LayoutParams(-1,pad(1)));}while(c.moveToNext());c.close();}
 void addDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(pad(8),0,pad(8),0);EditText title=new EditText(this);title.setHint("Description");form.addView(title);EditText amount=new EditText(this);amount.setHint("Amount in ₹");amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);form.addView(amount);EditText category=new EditText(this);category.setHint("Category (e.g. Food, Salary)");form.addView(category);final boolean[] isIncome={false};Switch sw=new Switch(this);sw.setText("This is income");sw.setOnCheckedChangeListener((v,on)->isIncome[0]=on);form.addView(sw);
  new AlertDialog.Builder(this).setTitle("Add transaction").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{double val=Double.parseDouble(amount.getText().toString());if(val>0){String t=title.getText().toString().trim();if(t.isEmpty())t="Transaction";String cat=category.getText().toString().trim();if(cat.isEmpty())cat="Uncategorised";db.add(t,val,isIncome[0],cat,"Manual","manual|"+System.currentTimeMillis());refresh();}}catch(Exception ignored){}}).show();
 }
}
